/// <summary>
/// The console entry point: builds the host, runs the census, and returns the exit code.
/// Kept public so the tests drive the same path <c>dotnet run</c> takes (P12.13 brief §6).
/// </summary>
public static class AutoWrongCensusCli
{
	/// <summary>Runs one census or pairs command and returns the process exit code.</summary>
	/// <param name="args">The command line: <c>census &lt;trace.jsonl&gt;</c> or <c>pairs &lt;census.tsv&gt; &lt;trace.jsonl&gt;</c>.</param>
