{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes (F-428 P12.13): the relation between the
/// accepted row (<c>actual*[0]</c>) and the key row (<c>expected*[0]</c>), and the site that
/// accepted it. All matching semantics come from the production helpers — <see cref="FdcNormalizer"/>,
/// <see cref="FdcMatcher.ExtractCandidateState(IReadOnlyList{string})"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers(IReadOnlyList{string})"/>,
/// <see cref="FdcDescriptionParser.Parse(string, FdcDataset, string)"/> and
/// <see cref="IngredientLineResolver.SingularizeToken(string)"/> — never from a copy (D-014).
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the trace carries no label row.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary>Relation: rawText names a can/jar unit; the key row is Canned, the accepted row is not.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase has two or more words and parsedName is only its first word.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: heads agree but the state masks differ.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary>Relation: heads and state agree but the dataset tier differs.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary>Relation: heads, state and tier agree; only qualifiers differ.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary>Relation: nothing above holds — a trace field was missing or the shapes do not fit.</summary>
	public const string RelationOther = "other";

	/// <summary>Site: the ranker accepted the row on a reused ingredient master/row.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the override path accepted the row.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue accepted the row.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker accepted the row without reuse.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-token buffer for the per-token state probe; the runner is single-threaded.
	private readonly string[] _singleToken = new string[1];

	/// <summary>Builds the classifier over the production normalizer and override-key index.</summary>
	/// <param name="normalizer">The production token normalizer.</param>
	/// <param name="overrideKeys">Keys of <c>exact-overrides.json</c> for the override-site column.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	/// <summary>Classifies one trace line; callers must pre-filter to <c>auto &amp;&amp; !correct</c>.</summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The relation, site and the audit fields for the TSV row.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = line.Atoms.FirstOrDefault(a => string.Equals(a.Outcome, "accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();
		var keyDesc = First(line.ExpectedDescriptions);
		var accDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var accTier = First(line.ActualDataTypes);
		var parsedName = atom?.ParsedName ?? string.Empty;
		var parsedTokens = SingularTokens(parsedName);

		var (site, overrideKey, knownSite) = ClassifySite(atom, line.RawText);

		var relation = RelationOther;
		string? missingField = null;
		IReadOnlyList<string>? keyOnlyQualifiers = null;
		IReadOnlyList<string>? acceptedOnlyQualifiers = null;
		var keyHeadPhrase = Array.Empty<string>();
		var acceptedStateText = string.Empty;
		var keyStateText = string.Empty;
		var tierDirection = string.Empty;
		bool? reusePhraseAgrees = null;

		if (!knownSite)
		{
			missingField = "atoms.path";
		}
		else if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = RelationNoLabel;
		}
		else if (string.IsNullOrWhiteSpace(accDesc))
		{
			missingField = "actualDescriptions";
		}
		else
		{
			var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
			var acceptedTokens = _normalizer.NormalizeToTokens(accDesc);
			var keyState = CombinedState(keyTokens);
			var acceptedState = CombinedState(acceptedTokens);
			keyHeadPhrase = KeyHeadPhrase(keyTokens);
			keyStateText = keyState.ToString();
			acceptedStateText = acceptedState.ToString();

			var keyHead = SingularTokens(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm);
			var acceptedHead = SingularTokens(FdcDescriptionParser.Parse(accDesc, DatasetOf(accTier)).HeadTerm);
			var headsAgree = keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase);

			if (PackUnitRegex().IsMatch(line.RawText)
				&& (keyState & FoodState.Canned) != FoodState.None
				&& (acceptedState & FoodState.Canned) == FoodState.None)
			{
				relation = RelationPackUnitState;
			}
			else if (keyHeadPhrase.Count >= 2
				&& parsedTokens.Count == 1
				&& string.Equals(parsedTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
			{
				relation = RelationCompoundHeadLost;
			}
			else if (headsAgree)
			{
				if (keyState != acceptedState)
				{
					relation = RelationStateMismatch;
				}
				else if (string.IsNullOrEmpty(accTier) || string.IsNullOrEmpty(keyTier))
				{
					missingField = "actualDataTypes";
				}
				else if (!string.Equals(accTier, keyTier, StringComparison.OrdinalIgnoreCase))
				{
					relation = RelationRowChoiceTier;
					tierDirection = TierRank(keyTier) >= TierRank(accTier) ? "key" : "accepted";
				}
				else
				{
					relation = RelationSameHeadOtherQualifier;
					var keyQualifiers = SingularSet(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).Qualifiers);
					var acceptedQualifiers = SingularSet(FdcDescriptionParser.Parse(accDesc, DatasetOf(accTier)).Qualifiers);
					keyOnlyQualifiers = keyQualifiers.Except(acceptedQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(q => q, StringComparer.Ordinal).ToArray();
					acceptedOnlyQualifiers = acceptedQualifiers.Except(keyQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(q => q, StringComparer.Ordinal).ToArray();
				}
			}
			else
			{
				relation = RelationSiblingFood;
			}
		}

		if (site == SiteReuse && atom?.LinkedIngredientId is { Length: > 0 } linked)
		{
			reusePhraseAgrees = IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linked);
		}

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = accTier,
			KeyTier = keyTier,
			AcceptedState = acceptedStateText,
			KeyState = keyStateText,
			ParsedName = parsedName,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = accDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
			TierDirection = tierDirection,
			ReusePhraseAgrees = reusePhraseAgrees,
		};
	}

	/// <summary>
	/// The key's head phrase: the normalized key tokens up to the first token production itself
	/// treats as state or modifier (<see cref="FdcLexicon.ModifierWords"/>, or a non-<see cref="FoodState.None"/>
	/// result from <see cref="FdcMatcher.ExtractCandidateState(IReadOnlyList{string})"/> /
	/// <see cref="FdcMatcher.ExtractCandidateSatisfiers(IReadOnlyList{string})"/> on the token alone).
	/// This is what makes "Bread, crumbs, dry, grated, plain" a two-word head ("bread crumbs") while
	/// "Nuts, almonds, blanched" keeps "blanched" out of the head.
	/// </summary>
	/// <param name="tokens">Normalized key tokens.</param>
	/// <returns>The head-phrase tokens (possibly empty).</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		ArgumentNullException.ThrowIfNull(tokens);

		var phrase = new List<string>();
		foreach (var token in tokens)
		{
			if (IsStateOrModifierToken(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>Maps a trace dataType string to the parser's dataset enum; unknown strings map to <see cref="FdcDataset.None"/> (curated parsing path).</summary>
	/// <param name="dataType">The dataType string from the trace.</param>
	/// <returns>The dataset for <see cref="FdcDescriptionParser.Parse(string, FdcDataset, string)"/>.</returns>
	public static FdcDataset DatasetOf(string dataType) =>
		Enum.TryParse(dataType, ignoreCase: true, out FdcDataset dataset) ? dataset : FdcDataset.None;

	/// <summary>Tier precedence: Foundation &gt; SrLegacy &gt; Survey &gt; Branded; unknown tiers rank 0.</summary>
	/// <param name="tier">The dataType string.</param>
	/// <returns>The precedence rank.</returns>
	public static int TierRank(string tier) => tier switch
	{
		"Foundation" => 4,
		"SrLegacy" => 3,
		"Survey" => 2,
		"Branded" => 1,
		_ => 0,
	};

	/// <summary>Production state mask: <see cref="FdcMatcher.ExtractCandidateState(IReadOnlyList{string})"/> ∪ <see cref="FdcMatcher.ExtractCandidateSatisfiers(IReadOnlyList{string})"/>.</summary>
	/// <param name="tokens">Normalized row tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens)
	{
		ArgumentNullException.ThrowIfNull(tokens);
		return FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);
	}

	private (string Site, string OverrideKey, bool Known) ClassifySite(TraceAtom? atom, string rawText)
	{
		if (atom is null)
		{
			return (string.Empty, string.Empty, knownSite: false);
		}

		switch (atom.Path)
		{
			case "override":
				return (SiteOverride, _overrideKeys.Contains(rawText) ? "yes" : "no", knownSite: true);
			case "curated":
				return (SiteCurated, string.Empty, knownSite: true);
			case "ranker":
				return (atom.Reused ? SiteReuse : SiteRanker, string.Empty, knownSite: true);
			default:
				return (string.Empty, string.Empty, knownSite: false);
		}
	}

	private bool IsStateOrModifierToken(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken[0] = token;
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private IReadOnlyList<string> SingularTokens(string text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static IReadOnlyList<string> SingularSet(IReadOnlyList<string> tokens) =>
		tokens.Select(IngredientLineResolver.SingularizeToken)
			.Distinct(StringComparer.OrdinalIgnoreCase)
			.OrderBy(t => t, StringComparer.Ordinal)
			.ToArray();

	private static string First(IReadOnlyList<string> list) => list.Count > 0 ? list[0] : string.Empty;

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();
}
