{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;

using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes: the relation between the accepted row
/// (<c>actual*[0]</c>) and the key row (<c>expected*[0]</c>), and the decision site
/// (atom <c>path</c> + <c>reused</c>). All grammar decisions come from the production helpers —
/// <see cref="FdcNormalizer.NormalizeToTokens(string?)"/>, <see cref="FdcMatcher.ExtractCandidateState(IReadOnlyList{string})"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers(IReadOnlyList{string})"/>, <see cref="FdcDescriptionParser.Parse(string, FdcDataset, string?)"/>
/// and <see cref="IngredientLineResolver.SingularizeToken(string)"/> — never from copies (D-014).
/// Not thread-safe: one runner thread drives it.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Expected row missing — relation <c>no-label</c>.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary>Can/jar unit line whose key row is <c>Canned</c> and whose accepted row is not.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary>The key head phrase is multi-word and parsedName is only its first word.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary>Head terms agree; the state masks differ.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary>Head terms and state agree; the dataset tiers differ.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary>Head terms, state and tier agree; the qualifier sets differ.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Head terms differ.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary>Catch-all: a field a relation check needed was missing, or nothing above held.</summary>
	public const string RelationOther = "other";

	/// <summary>Site: ranker path with <c>reused</c>.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: ranker path, not reused.</summary>
	public const string SiteRanker = "ranker";

	/// <summary>Site: override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: curated path.</summary>
	public const string SiteCurated = "curated";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reusable single-token carrier for the per-token state probes; the runner is single-threaded.
	private readonly string?[] _singleTokenScratch = new string?[1];

	/// <summary>Creates the classifier over the production normalizer and the exact-overrides key index.</summary>
	/// <param name="normalizer">The production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">Key index for <c>exact-overrides.json</c>.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>Classifies one trace line. Returns null when the line is not auto-wrong.</summary>
	/// <param name="line">A debug/batch trace line.</param>
	/// <returns>The classification, or <see langword="null"/> when <c>auto &amp;&amp; !correct</c> does not hold.</returns>
	public ClassificationResult? Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);
		if (!line.Auto || line.Correct)
		{
			return null;
		}

		var atom = PickAtom(line.Atoms);
		var (site, overrideKey) = ClassifySite(line.RawText, atom);
		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);
		var parsedNameTokens = SingularTokens(atom.ParsedName);

		var keyHeadPhrase = KeyHeadPhrase(_normalizer.NormalizeToTokens(keyDesc));
		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			ParsedName = atom.ParsedName,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
		};

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return result with { Relation = RelationNoLabel };
		}

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);
		result = result with { KeyState = keyState.ToString(), AcceptedState = acceptedState.ToString() };

		if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != 0
			&& (acceptedState & FoodState.Canned) == 0)
		{
			return result with { Relation = RelationPackUnitState };
		}

		if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return result with { Relation = RelationCompoundHeadLost };
		}

		var keyHead = SingularTokens(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm);
		var acceptedHead = SingularTokens(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).HeadTerm);
		var headsAgree = keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase);

		if (!headsAgree)
		{
			return result with { Relation = RelationSiblingFood };
		}

		if (keyState != acceptedState)
		{
			return result with { Relation = RelationStateMismatch };
		}

		if (string.IsNullOrEmpty(acceptedTier))
		{
			return result with { Relation = RelationOther, MissingField = "actualDataTypes" };
		}

		if (string.IsNullOrEmpty(keyTier))
		{
			return result with { Relation = RelationOther, MissingField = "expectedDataTypes" };
		}

		if (keyTier != acceptedTier)
		{
			return result with { Relation = RelationRowChoiceTier };
		}

		var keyQualifiers = SingularTokens(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).Qualifiers);
		var acceptedQualifiers = SingularTokens(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).Qualifiers);
		return result with
		{
			Relation = RelationSameHeadOtherQualifier,
			KeyOnlyQualifiers = keyQualifiers.Except(acceptedQualifiers, StringComparer.OrdinalIgnoreCase).ToArray(),
			AcceptedOnlyQualifiers = acceptedQualifiers.Except(keyQualifiers, StringComparer.OrdinalIgnoreCase).ToArray(),
		};
	}

	/// <summary>
	/// The key's head phrase: the normalized description tokens up to the first token production
	/// treats as state or a modifier (<c>ModifierWords</c> lexicon, or a non-<see cref="FoodState.None"/>
	/// result of <see cref="FdcMatcher.ExtractCandidateState(IReadOnlyList{string})"/> /
	/// <see cref="FdcMatcher.ExtractCandidateSatisfiers(IReadOnlyList{string})"/> on that single token).
	/// This is the multi-word head the single-token <see cref="ParsedFdcDescription.HeadTerm"/> cannot
	/// express — "Bread, crumbs, dry, grated, plain" yields "bread crumbs" here.
	/// </summary>
	/// <param name="tokens">Normalized description tokens.</param>
	/// <returns>The head phrase tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		ArgumentNullException.ThrowIfNull(tokens);
		var phrase = new List<string>(tokens.Count);
		foreach (var token in tokens)
		{
			if (CarriesStateToken(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>State mask of a row: <see cref="FdcMatcher.ExtractCandidateState(IReadOnlyList{string})"/> ∪ <see cref="FdcMatcher.ExtractCandidateSatisfiers(IReadOnlyList{string})"/> — the same pair production feeds <c>StateAgrees</c>.</summary>
	/// <param name="tokens">Normalized description tokens.</param>
	/// <returns>The combined state mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens)
	{
		ArgumentNullException.ThrowIfNull(tokens);
		return FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);
	}

	/// <summary>Folds raw line text into the lookup key form of the override shortcut: lower-cased, trimmed, everything from the first <c>(</c> dropped (the same fold <c>FdcMatcher.MatchAsync</c> applies before <c>TryGetRaw</c>; its <c>StripFromParenthesis</c> is private, so the fold is restated here and tested against the real file).</summary>
	/// <param name="rawText">Raw line text.</param>
	/// <returns>The folded lookup key.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
		ArgumentNullException.ThrowIfNull(rawText);
		var text = rawText.Trim();
		var paren = text.IndexOf('(', StringComparison.Ordinal);
		if (paren >= 0)
		{
			text = text[..paren];
		}

		return text.Trim().ToLowerInvariant();
	}

	/// <summary>Rank of a dataset tier: Foundation &gt; SrLegacy &gt; Survey &gt; Branded; 0 for unknown.</summary>
	/// <param name="tier">Tier name.</param>
	/// <returns>The rank.</returns>
	public static int TierRank(string tier) => tier switch
	{
		"Foundation" => 4,
		"SrLegacy" => 3,
		"Survey" => 2,
		"Branded" => 1,
		_ => 0,
	};

	private static TraceAtom PickAtom(IReadOnlyList<TraceAtom> atoms)
	{
		foreach (var atom in atoms)
		{
			if (string.Equals(atom.Outcome, "accepted", StringComparison.OrdinalIgnoreCase))
			{
				return atom;
			}
		}

		return atoms.Count > 0 ? atoms[0] : new TraceAtom();
	}

	private (string Site, string OverrideKey) ClassifySite(string rawText, TraceAtom atom)
	{
		if (string.Equals(atom.Path, "override", StringComparison.OrdinalIgnoreCase))
		{
			return (SiteOverride, _overrideKeys.IsKey(NormalizeForOverrideKey(rawText)) ? "yes" : "no");
		}

		if (string.Equals(atom.Path, "curated", StringComparison.OrdinalIgnoreCase))
		{
			return (SiteCurated, string.Empty);
		}

		if (string.Equals(atom.Path, "ranker", StringComparison.OrdinalIgnoreCase))
		{
			return (atom.Reused ? SiteReuse : SiteRanker, string.Empty);
		}

		return (string.Empty, string.Empty);
	}

	private IReadOnlyList<string> SingularTokens(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private IReadOnlyList<string> SingularTokens(IReadOnlyList<string> tokens) =>
		tokens.Select(IngredientLineResolver.SingularizeToken).ToArray();

	private bool CarriesStateToken(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleTokenScratch[0] = token;
		return FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();
}
