{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>The stdout/stderr sinks the runner writes to.</summary>
/// <param name="Output">TSV sink (production: <see cref="System.Console.Out"/>).</param>
/// <param name="Error">Summary/diagnostics sink (production: <see cref="System.Console.Error"/>).</param>
public sealed record OutputWriters(System.IO.TextWriter Output, System.IO.TextWriter Error);

/// <summary>Runs one census or pairs invocation over a trace.</summary>
public interface IAutoWrongCensusRunner
{
	/// <summary>Executes the invocation.</summary>
	/// <param name="cancellationToken">Cooperative cancellation token.</param>
	/// <returns>0 on success; 1 on a missing file, refused set, or unusable arguments.</returns>
	Task<int> RunAsync(CancellationToken cancellationToken);
}

/// <summary>
/// The census body: refuses non-debug/batch traces (D-029), classifies every
/// <c>auto &amp;&amp; !correct</c> line, writes the TSV to stdout and the relation × site summary to
/// stderr. All numbers in the summary come from the lines just classified — nothing is inferred.
/// </summary>
public sealed class AutoWrongCensusRunner : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private static readonly FrozenDictionary<string, int> TierRank = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase)
	{
		["Foundation"] = 4,
		["SrLegacy"] = 3,
		["Survey"] = 2,
		["Branded"] = 1,
	}.ToFrozenDictionary();

	private readonly AutoWrongCensusOptions _options;
	private readonly AutoWrongClassifier _classifier;
	private readonly OutputWriters _writers;

	/// <summary>Creates the runner.</summary>
	/// <param name="options">Bound CLI options.</param>
	/// <param name="classifier">The relation/site classifier.</param>
	/// <param name="writers">stdout/stderr sinks.</param>
	public AutoWrongCensusRunner(IOptions<AutoWrongCensusOptions> options, AutoWrongClassifier classifier, OutputWriters writers)
	{
		ArgumentNullException.ThrowIfNull(options);
		ArgumentNullException.ThrowIfNull(classifier);
		ArgumentNullException.ThrowIfNull(writers);
		_options = options.Value;
		_classifier = classifier;
		_writers = writers;
	}

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		if (_options.Command.Length == 0)
		{
			_writers.Error.WriteLine("usage: AutoWrongCensus census <trace.jsonl> | AutoWrongCensus pairs <census.tsv> <trace.jsonl> (see --help)");
			return 1;
		}

		if (!File.Exists(_options.TracePath))
		{
			_writers.Error.WriteLine($"refused: trace file '{_options.TracePath}' not found.");
			return 1;
		}

		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		if (!await RefuseForeignSetsAsync(lines, cancellationToken).ConfigureAwait(false))
		{
			return 1;
		}

		return _options.Command.Equals(CommandLineArgumentParser.PairsCommand, StringComparison.OrdinalIgnoreCase)
			? await RunPairsAsync(lines, cancellationToken).ConfigureAwait(false)
			: await RunCensusAsync(lines, cancellationToken).ConfigureAwait(false);
	}

	private static async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string path, CancellationToken cancellationToken)
	{
		var result = new List<TraceLine>();
		var lineNumber = 0;
		await foreach (var raw in File.ReadLines(path).GetAsyncEnumerator(cancellationToken))
		{
			lineNumber++;
			if (raw.Length == 0)
			{
				continue;
			}

			try
			{
				var parsed = JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions);
				if (parsed is null)
				{
					throw new InvalidOperationException("deserialized null");
				}

				result.Add(parsed);
			}
			catch (Exception ex) when (ex is JsonException or InvalidOperationException)
			{
				await Console.Error.WriteAsync($"refused: unreadable trace JSON on line {lineNumber}: {ex.Message}{Environment.NewLine}", cancellationToken).ConfigureAwait(false);
				return null;
			}
		}

		return result;
	}

	// D-029: a sealed (or otherwise foreign) set must never be classified.
	private async Task<bool> RefuseForeignSetsAsync(IReadOnlyList<TraceLine> lines, CancellationToken cancellationToken)
	{
		var refused = new SortedSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (var line in lines)
		{
			if (!line.Set.Equals("debug", StringComparison.OrdinalIgnoreCase) && !line.Set.Equals("batch", StringComparison.OrdinalIgnoreCase))
			{
				refused.Add(line.Set);
			}
		}

		if (refused.Count == 0)
		{
			return true;
		}

		await _writers.Error.WriteAsync($"refused: set(s) [{string.Join(", ", refused)}] — only debug and batch traces are classified (D-029).{Environment.NewLine}", cancellationToken).ConfigureAwait(false);
		return false;
	}

	private async Task<int> RunCensusAsync(IReadOnlyList<TraceLine> lines, CancellationToken cancellationToken)
	{
		var results = new List<ClassificationResult>();
		var reuseStats = new List<(string ParsedName, string? Linked)>();
		foreach (var line in lines)
		{
			if (!line.Auto || line.Correct)
			{
				continue;
			}

			var result = _classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				await _writers.Error.WriteAsync($"refused: unknown atom path on {line.HoldoutId}#{line.LineIndex}; the census cannot classify it.{Environment.NewLine}", cancellationToken).ConfigureAwait(false);
				return 1;
			}

			results.Add(result);
			if (result.Site == AutoWrongClassifier.SiteReuse)
			{
				var atom = line.Atoms.Count > 0 ? line.Atoms[0] : null;
				reuseStats.Add((atom?.ParsedName ?? string.Empty, atom?.LinkedIngredientId));
			}
		}

		await _writers.Output.WriteAsync("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText" + Environment.NewLine, cancellationToken).ConfigureAwait(false);
		foreach (var result in results)
		{
			await _writers.Output.WriteAsync(string.Join('\t',
				result.HoldoutId,
				result.LineIndex.ToString(System.Globalization.CultureInfo.InvariantCulture),
				result.Set,
				result.Relation,
				result.Site,
				result.OverrideKey,
				result.AcceptedTier,
				result.KeyTier,
				result.AcceptedState,
				result.KeyState,
				Clean(result.ParsedName),
				result.KeyHead,
				Clean(result.AcceptedDesc),
				Clean(result.KeyDesc),
				Clean(result.RawText)) + Environment.NewLine, cancellationToken).ConfigureAwait(false);
		}

		await WriteSummaryAsync(lines, results, reuseStats, cancellationToken).ConfigureAwait(false);
		return 0;
	}

	private async Task WriteSummaryAsync(IReadOnlyList<TraceLine> lines, IReadOnlyList<ClassificationResult> results, IReadOnlyList<(string ParsedName, string? Linked)> reuseStats, CancellationToken cancellationToken)
	{
		var setError = new SortedSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (var line in lines)
		{
			setError.Add(line.Set);
		}

		await _writers.Error.WriteAsync($"autoWrongCensus set(s)=[{string.Join(", ", setError)}] traceLines={lines.Count} autoWrongLines={results.Count}" + Environment.NewLine, cancellationToken).ConfigureAwait(false);

		await _writers.Error.WriteAsync("relation\tsite\tcount" + Environment.NewLine, cancellationToken).ConfigureAwait(false);
		foreach (var group in results.GroupBy(r => (r.Relation, r.Site)).OrderBy(g => g.Key.Item1, StringComparer.Ordinal).ThenBy(g => g.Key.Item2, StringComparer.Ordinal))
		{
			await _writers.Error.WriteAsync($"{group.Key.Item1}\t{group.Key.Item2}\t{group.Count().ToString(System.Globalization.CultureInfo.InvariantCulture)}" + Environment.NewLine, cancellationToken).ConfigureAwait(false);
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		var otherPct = results.Count == 0 ? 0d : otherCount * 100d / results.Count;
		await _writers.Error.WriteAsync($"relation 'other': {otherCount.ToString(System.Globalization.CultureInfo.InvariantCulture)}/{results.Count.ToString(System.Globalization.CultureInfo.InvariantCulture)} = {otherPct.ToString("F1", System.Globalization.CultureInfo.InvariantCulture)}%" + Environment.NewLine, cancellationToken).ConfigureAwait(false);

		foreach (var missing in results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField!).OrderBy(g => g.Key, StringComparer.Ordinal))
		{
			await _writers.Error.WriteAsync($"missing trace field '{missing.Key}': {missing.Count().ToString(System.Globalization.CultureInfo.InvariantCulture)} line(s)" + Environment.NewLine, cancellationToken).ConfigureAwait(false);
		}

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToArray();
		var overrideKeyHits = overrideLines.Count(r => r.OverrideKey == "yes");
		await _writers.Error.WriteAsync($"override-site lines with normalized rawText as exact-overrides.json key: {overrideKeyHits.ToString(System.Globalization.CultureInfo.InvariantCulture)}/{overrideLines.Length.ToString(System.Globalization.CultureInfo.InvariantCulture)}" + Environment.NewLine, cancellationToken).ConfigureAwait(false);

		var reuseFalse = reuseStats.Count(s => s.Linked is null || !IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(s.ParsedName), s.Linked));
		await _writers.Error.WriteAsync($"reuse-site lines where ShouldReuse(parsedName, linkedIngredientId) is false: {reuseFalse.ToString(System.Globalization.CultureInfo.InvariantCulture)}/{reuseStats.Count.ToString(System.Globalization.CultureInfo.InvariantCulture)}" + Environment.NewLine, cancellationToken).ConfigureAwait(false);

		var tierRows = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToArray();
		var keyHigher = tierRows.Count(r => TierRank.GetValueOrDefault(r.KeyTier, 0) > TierRank.GetValueOrDefault(r.AcceptedTier, 0));
		await _writers.Error.WriteAsync($"row-choice-tier: key tier higher={keyHigher.ToString(System.Globalization.CultureInfo.InvariantCulture)} / accepted tier higher={tierRows.Length - keyHigher} (Foundation>SrLegacy>Survey>Branded)" + Environment.NewLine, cancellationToken).ConfigureAwait(false);

		foreach (var qualifierRow in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			await _writers.Error.WriteAsync($"same-head-other-qualifier {qualifierRow.HoldoutId}#{qualifierRow.LineIndex.ToString(System.Globalization.CultureInfo.InvariantCulture)}: key-only=[{string.Join(' ', qualifierRow.KeyOnlyQualifiers ?? [])}] accepted-only=[{string.Join(' ', qualifierRow.AcceptedOnlyQualifiers ?? [])}]" + Environment.NewLine, cancellationToken).ConfigureAwait(false);
		}
	}

	private async Task<int> RunPairsAsync(IReadOnlyList<TraceLine> lines, CancellationToken cancellationToken)
	{
		if (!File.Exists(_options.CensusTsvPath))
		{
			await _writers.Error.WriteAsync($"refused: census TSV '{_options.CensusTsvPath}' not found.{Environment.NewLine}", cancellationToken).ConfigureAwait(false);
			return 1;
		}

		var censusRows = await ReadWindowRowsAsync(_options.CensusTsvPath, cancellationToken).ConfigureAwait(false);
		if (censusRows is null)
		{
			return 1;
		}

		var traceIndex = new Dictionary<string, TraceLine>(StringComparer.Ordinal);
		foreach (var line in lines)
		{
			traceIndex[$"{line.HoldoutId}\u0000{line.LineIndex.ToString(System.Globalization.CultureInfo.InvariantCulture)}"] = line;
		}

		await _writers.Output.WriteAsync("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText" + Environment.NewLine, cancellationToken).ConfigureAwait(false);
		var emitted = 0;
		var missingInTrace = 0;
		foreach (var (holdoutId, lineIndex) in censusRows)
		{
			if (!traceIndex.TryGetValue($"{holdoutId}\u0000{lineIndex}", out var traceLine))
			{
				missingInTrace++;
				continue;
			}

			var atom = traceLine.Atoms.Count > 0 ? traceLine.Atoms[0] : null;
			var parsedNameHead = string.Join(' ', SingularTokensOf(atom?.ParsedName ?? string.Empty));
			var keyHead = string.Join(' ', _classifier.KeyHeadPhrase(SingularTokensOf(FirstOrNull(traceLine.ExpectedDescriptions))));
			await _writers.Output.WriteAsync(string.Join('\t', holdoutId, lineIndex, parsedNameHead, keyHead, Clean(traceLine.RawText)) + Environment.NewLine, cancellationToken).ConfigureAwait(false);
			emitted++;
		}

		await _writers.Error.WriteAsync($"pairs: census window/compound-or-other rows={censusRows.Count.ToString(System.Globalization.CultureInfo.InvariantCulture)} emitted={emitted.ToString(System.Globalization.CultureInfo.InvariantCulture)} missingInTrace={missingInTrace.ToString(System.Globalization.CultureInfo.InvariantCulture)}" + Environment.NewLine, cancellationToken).ConfigureAwait(false);
		return 0;
	}

	private static async Task<IReadOnlyList<(string HoldoutId, string LineIndex)>?> ReadWindowRowsAsync(string path, CancellationToken cancellationToken)
	{
		var rows = new List<(string, string)>();
		var headerSeen = false;
		var holdoutCol = -1;
		var lineIndexCol = -1;
		var blockerCol = -1;
		var routeCol = -1;

		await foreach (var raw in File.ReadLines(path).GetAsyncEnumerator(cancellationToken))
		{
			var cells = raw.Split('\t');
			if (!headerSeen)
			{
				holdoutCol = Array.IndexOf(cells, "holdoutId");
				lineIndexCol = Array.IndexOf(cells, "lineIndex");
				blockerCol = Array.IndexOf(cells, "blocker");
				routeCol = Array.IndexOf(cells, "route");
				if (holdoutCol < 0 || lineIndexCol < 0 || blockerCol < 0 || routeCol < 0)
				{
					await Console.Error.WriteAsync($"refused: census TSV header lacks holdoutId/lineIndex/blocker/route.{Environment.NewLine}", cancellationToken).ConfigureAwait(false);
					return null;
				}

				headerSeen = true;
				continue;
			}

			if (cells.Length <= Math.Max(blockerCol, routeCol))
			{
				continue;
			}

			if (cells[blockerCol] == "window" && (cells[routeCol] == "compound" || cells[routeCol] == "other"))
			{
				rows.Add((cells[holdoutCol], cells[lineIndexCol]));
			}
		}

		return rows;
	}

	private static string Clean(string text) => text.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private IReadOnlyList<string> SingularTokensOf(string text) => SingularTokens(_classifier, text);

	private static IReadOnlyList<string> SingularTokens(AutoWrongClassifier classifier, string text) =>
		classifier.KeyHeadPhrase(SingularTokensRaw(text));

	private static IReadOnlyList<string> SingularTokensRaw(string text) =>
		Array.ConvertAll(text.ToLowerInvariant().Split(' ', StringSplitOptions.RemoveEmptyEntries), t => IngredientLineResolver.SingularizeToken(t));

	private static string FirstOrNull(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;
}
