{"content":"using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Services;
using LetUsCook.Fdc.Lexicon;

using Shouldly;

using Xunit;

namespace LetUsCook.AutoWrongCensus.Tests.Services;

/// <summary>
/// Relation and site classification through the production helpers. Every fixture line is shaped
/// like a real HoldoutGate trace record (the §2 examples verbatim from <c>runs/P12.7/base-debug.jsonl</c>).
/// </summary>
public sealed class AutoWrongClassifierTests : IDisposable
{
	private readonly AutoWrongClassifier _classifier = new(new FdcNormalizer(), new ExactOverrideKeyIndex());

	public void Dispose()
	{
		_classifier.ShouldNotBeNull();
	}

	[Fact]
	public void CanUnitWithCannedKeyOnNonCannedRowIsPackUnitStateOnReuse()
	{
		// §2 example 1, verbatim from the P12.7 debug trace.
		var result = _classifier.Classify(Line(
			"1 (28 ounce) can crushed tomatoes",
			["Tomatoes, crushed, canned"], ["Foundation"],
			["Tomato, roma"], ["Foundation"],
			Atom(path: "ranker", reused: true, parsedName: "tomatoes", linked: "tomato")));

		result.Relation.ShouldBe(AutoWrongClassifier.RelationPackUnitState);
		result.Site.ShouldBe(AutoWrongClassifier.SiteReuse);
		result.KeyState.ShouldBe("Canned");
		result.AcceptedState.ShouldBe("None");
		result.OverrideKey.ShouldBe(string.Empty);
	}

	[Fact]
	public void JarUnitWithCannedKeyIsPackUnitStateToo()
	{
		var result = _classifier.Classify(Line(
			"1 (4 ounce) jar apricot baby food",
			["Apricots, canned, drained, packed in heavy syrup, sweetened"], ["Branded"],
			["Apricots, raw"], ["SrLegacy"],
			Atom(path: "ranker", reused: true, parsedName: "apricots", linked: "apricot")));

		result.Relation.ShouldBe(AutoWrongClassifier.RelationPackUnitState);
	}

	[Fact]
	public void BreadCrumbsLineWithFirstWordOnlyParsedNameIsCompoundHeadLostOnOverride()
	{
		// §2 example 2, verbatim. The key head phrase is "bread crumb" (production state extraction
		// first fires on "dry"); parsedName "bread" equals only its first word.
		var result = _classifier.Classify(Line(
			"3 cups bread crumbs, or as needed",
			["Bread, crumbs, dry, grated, plain"], ["SrLegacy"],
			["Bread, white, commercially prepared (includes soft bread crumbs)"], ["SrLegacy"],
			Atom(path: "override", reused: true, parsedName: "bread", linked: "bread")));

		result.Relation.ShouldBe(AutoWrongClassifier.RelationCompoundHeadLost);
		result.Site.ShouldBe(AutoWrongClassifier.SiteOverride);
		result.KeyHead.ShouldBe("bread crumb");
		result.OverrideKey.ShouldBe("no");
	}

	[Fact]
	public void BlanchedAlmondsLineIsStateMismatchOnReuse()
	{
		// §2 example 3, verbatim. Heads agree (almond); the accepted row carries Raw and the key does not.
		var result = _classifier.Classify(Line(
			"1/2 cup finely chopped blanched almonds",
			["Nuts, almonds, blanched"], ["SrLegacy"],
			["Nuts, almonds, whole, raw"], ["Foundation"],
			Atom(path: "ranker", reused: true, parsedName: "almonds", linked: "almond")));

		result.Relation.ShouldBe(AutoWrongClassifier.RelationStateMismatch);
		result.Site.ShouldBe(AutoWrongClassifier.SiteReuse);
		result.AcceptedState.ShouldBe("Raw");
		result.KeyState.ShouldBe("None");
	}

	[Fact]
	public void SameHeadSameStateDifferentTierIsRowChoiceTier()
	{
		var result = _classifier.Classify(Line(
			"2 carrots, chopped",
			["Carrots, raw"], ["SrLegacy"],
			["Carrots, raw"], ["Foundation"],
			Atom(path: "ranker", reused: true, parsedName: "carrots", linked: "carrot")));

		result.Relation.ShouldBe(AutoWrongClassifier.RelationRowChoiceTier);
		result.KeyTier.ShouldBe("SrLegacy");
		result.AcceptedTier.ShouldBe("Foundation");
	}

	[Fact]
	public void MissingAcceptedTierFallsToOtherAndNamesTheField()
	{
		var result = _classifier.Classify(Line(
			"1 stalk celery, chopped",
			["Celery, leaves"], ["SrLegacy"],
			["Celery"], [],
			Atom(path: "ranker", reused: true, parsedName: "celery leaves", linked: "celery")));

		result.Relation.ShouldBe(AutoWrongClassifier.RelationOther);
		result.MissingField.ShouldBe("actualDataTypes");
	}

	[Fact]
	public void SameHeadSameStateSameTierDifferentQualifiersRecordsTheDiff()
	{
		var result = _classifier.Classify(Line(
			"1 cup milk, low fat",
			["Milk, low fat, with calcium added"], ["SrLegacy"],
			["Milk, low fat"], ["SrLegacy"],
			Atom(path: "ranker", reused: false, parsedName: "low fat milk")));

		result.Relation.ShouldBe(AutoWrongClassifier.RelationSameHeadOtherQualifier);
		result.Site.ShouldBe(AutoWrongClassifier.SiteRanker);
		result.KeyOnlyQualifiers.ShouldNotBeNull();
		result.KeyOnlyQualifiers!.ShouldContain("calcium");
		result.AcceptedOnlyQualifiers!.ShouldBeEmpty();
	}

	[Fact]
	public void DifferentHeadTermsAreSiblingFood()
	{
		var result = _classifier.Classify(Line(
			"1 onion, diced",
			["Onions, raw"], ["SrLegacy"],
			["Garlic, raw"], ["Foundation"],
			Atom(path: "override", reused: false, parsedName: "onion")));

		result.Relation.ShouldBe(AutoWrongClassifier.RelationSiblingFood);
		result.Site.ShouldBe(AutoWrongClassifier.SiteOverride);
	}

	[Fact]
	public void EmptyExpectedDescriptionsIsNoLabel()
	{
		var result = _classifier.Classify(Line(
			"1 tsp salt",
			[], [],
			["Salt, table, iodized"], ["Foundation"],
			Atom(path: "curated", reused: false, parsedName: "salt")));

		result.Relation.ShouldBe(AutoWrongClassifier.RelationNoLabel);
		result.MissingField.ShouldBe("expectedDescriptions");
		result.Site.ShouldBe(AutoWrongClassifier.SiteCurated);
	}

	[Fact]
	public void OverrideRawTextInExactOverridesFileIsKeyedYes()
	{
		// "amaretto" is a real key in the shipped exact-overrides.json.
		var result = _classifier.Classify(Line(
			"amaretto",
			["Cherries, sour, red"], ["SrLegacy"],
			["Cherries, sour, maraschino, glazed"], ["Branded"],
			Atom(path: "override", reused: false, parsedName: "amaretto")));

		result.Site.ShouldBe(AutoWrongClassifier.SiteOverride);
		result.OverrideKey.ShouldBe("yes");
	}

	[Fact]
	public void UnknownAtomPathYieldsNoSite()
	{
		var result = _classifier.Classify(Line(
			"1 thing",
			["Salt, table, iodized"], ["Foundation"],
			["Salt, table, iodized"], ["Foundation"],
			Atom(path: "mystery", reused: false, parsedName: "thing")));

		result.Site.ShouldBe(string.Empty);
	}

	[Fact]
	public void KeyHeadPhraseStopsAtFirstProductionStateToken()
	{
		var normalizer = new FdcNormalizer();
		var phrase = _classifier.KeyHeadPhrase(normalizer.NormalizeToTokens("Bread, crumbs, dry, grated, plain"));
		phrase.ShouldBe(["bread", "crumb"]);

		var canned = _classifier.KeyHeadPhrase(normalizer.NormalizeToTokens("Tomatoes, crushed, canned"));
		canned.ShouldBe(["tomato", "crushed"]);
	}

	[Fact]
	public void AcceptedAtomIsChosenWhenLineSplits()
	{
		var line = Line(
			"2 cups flour or 1 cup almond flour",
			["Flours, all purpose, enriched, bleached"], ["SrLegacy"],
			["Flours, all purpose, unbleached, enriched"], ["SrLegacy"],
			Atom(path: "ranker", reused: true, parsedName: "flour", outcome: "deferred"),
			Atom(path: "ranker", reused: true, parsedName: "flour", outcome: "accepted"));

		var result = _classifier.Classify(line);
		result.Relation.ShouldBe(AutoWrongClassifier.RelationSameHeadOtherQualifier);
	}

	private static TraceLine Line(
		string rawText,
		string[] expectedDescriptions,
		string[] expectedDataTypes,
		string[] actualDescriptions,
		string[] actualDataTypes,
		params TraceAtom[] atoms) => new()
	{
		RawText = rawText,
		HoldoutId = "debug:census-test",
		LineIndex = 0,
		Set = "debug",
		Auto = true,
		Correct = false,
		ExpectedDescriptions = expectedDescriptions,
		ExpectedDataTypes = expectedDataTypes,
		ActualDescriptions = actualDescriptions,
		ActualDataTypes = actualDataTypes,
		Atoms = atoms,
	};

	private static TraceAtom Atom(
		string path,
		bool reused,
		string parsedName,
		string? linked = null,
		string outcome = "accepted") => new()
	{
		Path = path,
		Reused = reused,
		ParsedName = parsedName,
		LinkedIngredientId = linked,
		Outcome = outcome,
	};
}
