{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;

using Shouldly;

using Xunit;

namespace LetUsCook.AutoWrongCensus.Tests.Services;

/// <summary>
/// The CLI contract (F-428 P12.13 §4): golden TSV through the real host graph, refusal exits, and the
/// stderr summary agreeing with the stdout rows. Every run goes through
/// <see cref="AutoWrongCensusCli.RunAsync(string[], System.IO.TextWriter?, System.IO.TextWriter?)"/> —
/// the same entry <c>Program.cs</c> uses.
/// </summary>
public sealed class AutoWrongCensusCliTests : IDisposable
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly string _dir;

	/// <summary>Creates a per-test temp directory for trace fixtures.</summary>
	public AutoWrongCensusCliTests()
	{
		_dir = Path.Combine(Path.GetTempPath(), "f428-p1213-" + Guid.NewGuid().ToString("N"));
		Directory.CreateDirectory(_dir);
	}

	public void Dispose()
	{
		try
		{
			Directory.Delete(_dir, recursive: true);
		}
		catch (IOException)
		{
			// Best-effort cleanup of the temp fixture dir.
		}
	}

	[Fact]
	public async Task RunAsyncReturnsZeroOnHelp()
	{
		(await AutoWrongCensusCli.RunAsync(["--help"])).ShouldBe(0);
		(await AutoWrongCensusCli.RunAsync(["-h"])).ShouldBe(0);
	}

	[Fact]
	public async Task CensusOnMissingTraceExitsOneWithRefusalOnStderrAndNothingOnStdout()
	{
		var output = new StringWriter();
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["census", Path.Combine(_dir, "nope.jsonl")], output, error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("not found");
		output.ToString().ShouldBeEmpty();
	}

	[Fact]
	public async Task CensusRefusesASealedTraceAndWritesNoRows(D-029)
	{
		var trace = WriteTrace(
		[
			Line("debug:x", "debug", auto: true, correct: false),
			Line("sealed:y", "sealed", auto: true, correct: false),
		]);
		var output = new StringWriter();
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["census", trace], output, error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("refused: set 'sealed'");
		output.ToString().ShouldBeEmpty();
	}

	[Fact]
	public async Task CensusRefusesAnySetThatIsNotDebugOrBatch()
	{
		var trace = WriteTrace([Line("holdout:z", "holdout", auto: true, correct: false)]);
		var output = new StringWriter();
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["census", trace], output, error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("D-029");
		output.ToString().ShouldBeEmpty();
	}

	[Fact]
	public async Task CensusRefusesAnAtomPathThatIsNotRankerOverrideOrCurated()
	{
		var trace = WriteTrace([
			Line("debug:w", "debug", auto: true, correct: false, path: "hand-fed"),
		]);
		var output = new StringWriter();
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["census", trace], output, error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("not ranker|override|curated");
		output.ToString().ShouldBeEmpty();
	}

	[Fact]
	public async Task UnusableArgumentsExitOneWithUsageOnStderr()
	{
		var output = new StringWriter();
		var error = new StringWriter();

		(await AutoWrongCensusCli.RunAsync([], output, error)).ShouldBe(1);
		error.ToString().ShouldContain("usage:");

		var error2 = new StringWriter();
		(await AutoWrongCensusCli.RunAsync(["census"], new StringWriter(), error2)).ShouldBe(1);
		error2.ToString().ShouldContain("usage:");
	}

	[Fact]
	public async Task CensusGoldenWritesTheFullTsvThroughTheHostGraph()
	{
		var trace = WriteTrace(GoldenLines());
		var output = new StringWriter();
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["census", trace], output, error);

		exit.ShouldBe(0);
		output.ToString().ReplaceLineEndings("\n").ShouldBe(GoldenTsv);
		error.ToString().ShouldNotContain("Hosting environment");
	}

	[Fact]
	public async Task CensusSummaryMatrixEqualsTheTsvRelationSiteCounts()
	{
		var trace = WriteTrace(GoldenLines());
		var output = new StringWriter();
		var error = new StringWriter();

		(await AutoWrongCensusCli.RunAsync(["census", trace], output, error)).ShouldBe(0);

		var tsv = output.ToString().ReplaceLineEndings("\n").Split('\n');
		var header = tsv[0].Split('\t');
		var relationIndex = Array.IndexOf(header, "relation");
		var siteIndex = Array.IndexOf(header, "site");
		var counts = tsv.Skip(1)
			.Where(l => l.Length > 0)
			.GroupBy(l => (cells: l.Split('\t'), key: l.Split('\t')[relationIndex] + "\t" + l.Split('\t')[siteIndex]))
			.ToDictionary(g => g.Key.key, g => g.Count());

		var summary = error.ToString().ReplaceLineEndings("\n").Split('\n');
		var matrixStart = Array.IndexOf(summary, "relation\tsite\tcount") + 1;
		var matrixRows = summary[matrixStart..].TakeWhile(l => l.Contains('\t')).ToArray();
		var summaryCounts = matrixRows
			.Select(r => r.Split('\t'))
			.ToDictionary(c => c[0] + "\t" + c[1], c => int.Parse(c[2], System.Globalization.CultureInfo.InvariantCulture));

		summaryCounts.ShouldBe(counts);
	}

	[Fact]
	public async Task PairsEmitsOnlyWindowCompoundAndOtherRowsFromTheCensusTsv()
	{
		var trace = WriteTrace([
			Line("debug:a", "debug", auto: false, correct: false, key: "Bread, crumbs, dry, grated, plain", parsed: "bread"),
			Line("debug:b", "debug", auto: false, correct: false, key: "Onions, raw", parsed: "onion"),
			Line("debug:c", "debug", auto: false, correct: false, key: "Carrots, raw", parsed: "carrots"),
			Line("debug:d", "debug", auto: false, correct: false, key: "Rice, white, long grain, parboiled, cooked", parsed: "rice"),
		]);
		var census = Path.Combine(_dir, "census.tsv");
		await File.WriteAllTextAsync(census,
			"holdoutId\tlineIndex\tblocker\troute\n" +
			"debug:a\t0\twindow\tcompound\n" +
			"debug:b\t0\twindow\tother\n" +
			"debug:c\t0\tmapping-reuse\tcompound\n" +
			"debug:d\t0\twindow\tparser-word-lost\n");

		var output = new StringWriter();
		var error = new StringWriter();
		var exit = await AutoWrongCensusCli.RunAsync(["pairs", census, trace], output, error);

		exit.ShouldBe(0);
		var lines = output.ToString().ReplaceLineEndings("\n").Split('\n');
		lines[0].ShouldBe("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		lines[1].ShouldStartWith("debug:a\t0\tbread\tbread crumb\t");
		lines[2].ShouldStartWith("debug:b\t0\tonion\tonion\t");
		lines[3].ShouldBeEmpty();
		error.ToString().ShouldContain("pairs emitted=2 unmatchedCensusRows=0");
	}

	[Fact]
	public async Task PairsRefusesAMissingCensusTsv()
	{
		var trace = WriteTrace([Line("debug:a", "debug", auto: false, correct: false)]);
		var output = new StringWriter();
		var error = new StringWriter();

		var exit = await AutoWrongCensusCli.RunAsync(["pairs", Path.Combine(_dir, "nope.tsv"), trace], output, error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("census TSV");
		output.ToString().ShouldBeEmpty();
	}

	[Fact]
	public async Task PairsRefusesATraceWithADisallowedSet()
	{
		var trace = WriteTrace([Line("sealed:a", "sealed", auto: false, correct: false)]);
		var census = Path.Combine(_dir, "census.tsv");
		await File.WriteAllTextAsync(census, "holdoutId\tlineIndex\tblocker\troute\n");

		var output = new StringWriter();
		var error = new StringWriter();
		var exit = await AutoWrongCensusCli.RunAsync(["pairs", census, trace], output, error);

		exit.ShouldBe(1);
		error.ToString().ShouldContain("refused: set 'sealed'");
		output.ToString().ShouldBeEmpty();
	}

	private string WriteTrace(string[] jsonLines)
	{
		var path = Path.Combine(_dir, "trace.jsonl");
		File.WriteAllLines(path, jsonLines);
		return path;
	}

	private static string Line(
		string holdoutId,
		string set,
		bool auto,
		bool correct,
		string path = "ranker",
		bool reused = false,
		string key = "Carrots, raw",
		string parsed = "carrots") =>
		JsonSerializer.Serialize(
			new TraceLine
			{
				RawText = parsed + " raw",
				HoldoutId = holdoutId,
				LineIndex = 0,
				Set = set,
				Auto = auto,
				Correct = correct,
				ExpectedDescriptions = [key],
				ExpectedDataTypes = ["SrLegacy"],
				ActualDescriptions = ["Carrots, raw"],
				ActualDataTypes = ["Foundation"],
				Atoms = [new TraceAtom { Path = path, Reused = reused, ParsedName = parsed, Outcome = "accepted" }],
			},
			JsonOptions);

	private static string[] GoldenLines() =>
	[
		JsonSerializer.Serialize(new TraceLine
		{
			RawText = "2 tsp good olive oil", HoldoutId = "debug:nolabel", LineIndex = 0, Set = "debug", Auto = true, Correct = false,
			ExpectedDescriptions = [], ExpectedDataTypes = [],
			ActualDescriptions = ["Oil, olive, salad or cooking"], ActualDataTypes = ["SrLegacy"],
			Atoms = [new TraceAtom { Path = "curated", Reused = true, ParsedName = "olive oil", Outcome = "accepted" }],
		}, JsonOptions),
		JsonSerializer.Serialize(new TraceLine
		{
			RawText = "1 (28 ounce) can crushed tomatoes", HoldoutId = "debug:cans", LineIndex = 1, Set = "debug", Auto = true, Correct = false,
			ExpectedDescriptions = ["Tomatoes, crushed, canned"], ExpectedDataTypes = ["Foundation"],
			ActualDescriptions = ["Tomato, roma"], ActualDataTypes = ["Foundation"],
			Atoms = [new TraceAtom { Path = "ranker", Reused = true, ParsedName = "tomatoes", LinkedIngredientId = "tomato", Outcome = "accepted" }],
		}, JsonOptions),
		JsonSerializer.Serialize(new TraceLine
		{
			RawText = "3 cups bread crumbs, or as needed", HoldoutId = "debug:crumbs", LineIndex = 2, Set = "debug", Auto = true, Correct = false,
			ExpectedDescriptions = ["Bread, crumbs, dry, grated, plain"], ExpectedDataTypes = ["SrLegacy"],
			ActualDescriptions = ["Bread, white, commercially prepared (includes soft bread crumbs)"], ActualDataTypes = ["SrLegacy"],
			Atoms = [new TraceAtom { Path = "override", Reused = true, ParsedName = "bread", LinkedIngredientId = "bread", Outcome = "accepted" }],
		}, JsonOptions),
		JsonSerializer.Serialize(new TraceLine
		{
			RawText = "1/2 cup finely chopped blanched almonds", HoldoutId = "debug:almonds", LineIndex = 3, Set = "debug", Auto = true, Correct = false,
			ExpectedDescriptions = ["Nuts, almonds, blanched"], ExpectedDataTypes = ["SrLegacy"],
			ActualDescriptions = ["Nuts, almonds, whole, raw"], ActualDataTypes = ["Foundation"],
			Atoms = [new TraceAtom { Path = "ranker", Reused = true, ParsedName = "almonds", LinkedIngredientId = "almond", Outcome = "accepted" }],
		}, JsonOptions),
		JsonSerializer.Serialize(new TraceLine
		{
			RawText = "2 carrots, chopped", HoldoutId = "debug:tier", LineIndex = 4, Set = "debug", Auto = true, Correct = false,
			ExpectedDescriptions = ["Carrots, raw"], ExpectedDataTypes = ["SrLegacy"],
			ActualDescriptions = ["Carrots, raw"], ActualDataTypes = ["Foundation"],
			Atoms = [new TraceAtom { Path = "ranker", Reused = true, ParsedName = "carrots", LinkedIngredientId = "carrot", Outcome = "accepted" }],
		}, JsonOptions),
		JsonSerializer.Serialize(new TraceLine
		{
			RawText = "1 cup 2% milk", HoldoutId = "debug:milk", LineIndex = 5, Set = "debug", Auto = true, Correct = false,
