{"new_string":"	/// <summary>
	/// Whether any token of the key head phrase beyond its first word also appears in the normalized,
	/// singularised rawText — evidence that the recipe actually named the full two-word head and the
	/// parsed name kept only its first word (brief §3 relation 3's "lost head"), rather than the key
	/// description merely being wordy about a one-word food ("2 cups flour" vs "Flour, wheat,
	/// all-purpose, enriched, bleached").
	/// </summary>
	private static bool CarriesHeadTailEvidence(string[] keyHeadPhrase, string[] rawTextTokens)
	{
		for (var i = 1; i < keyHeadPhrase.Length; i++)
		{
			if (rawTextTokens.Contains(keyHeadPhrase[i], StringComparer.OrdinalIgnoreCase))
			{
				return true;
			}
		}

		return false;
	}

