import csv, re

RELATIONS={'pack-unit-state','compound-head-lost','state-mismatch','sibling-food','row-choice-tier','same-head-other-qualifier','no-label','other'}
SITES={'override','reuse','ranker','curated'}

def sing(tok):
    t=tok
    if t.endswith('ies'): return t[:-3]+'y'
    if len(t)>4 and t.endswith('es') and t[-3] in 'sxz' or t.endswith(('ches','shes')): return t[:-2]
    if t.endswith('s') and not t.endswith('ss'): return t[:-1]
    return t

def raw_tokens(s):
    return {sing(w) for w in re.findall(r'[a-z]+', s.lower())}

for f in ('autowrong-debug.tsv','autowrong-batch.tsv'):
    rows=list(csv.DictReader(open(f),delimiter='\t'))
    badrel=[r for r in rows if r['relation'] not in RELATIONS]
    badsite=[r for r in rows if r['site'] not in SITES]
    other=[r for r in rows if r['relation']=='other']
    ch=[r for r in rows if r['relation']=='compound-head-lost']
    noev=[]
    for r in ch:
        head=r['keyHead'].split()
        if len(head)<2: noev.append((r['holdoutId'],r['rawText'],r['keyHead'],'head<2')); continue
        rt=raw_tokens(r['rawText'])
        if not any(t in rt for t in head[1:]):
            noev.append((r['holdoutId'],r['rawText'],r['keyHead']))
    print(f, 'rows=',len(rows), 'badRelation=',len(badrel), 'badSite=',len(badsite), 'other=',len(other),
          'compound=',len(ch), 'compound-no-evidence=',len(noev))
    for n in noev: print('   NOEV:',n)
